### App.tsx
```tsx
import { useState } from 'react';
import Sidebar from './Sidebar';
import UserCard from './UserCard';

export default function App() {
  const [activeLink, setActiveLink] = useState('Profile');

  return (
    <div className="flex h-screen bg-gray-50">
      <Sidebar activeLink={activeLink} setActiveLink={setActiveLink} />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white border-b border-gray-200 p-4 flex items-center justify-between">
          <h1 className="text-xl font-semibold text-gray-800">Dashboard</h1>
          <div className="flex items-center space-x-4">
            <span className="text-sm text-gray-600">Welcome back, Alex!</span>
          </div>
        </header>
        <main className="flex-1 p-6 overflow-y-auto">
          <div className="max-w-4xl mx-auto">
            <h2 className="text-2xl font-bold text-gray-800 mb-6">Settings</h2>
            <p className="text-gray-600 mb-8">
              Manage your account settings, team, and notifications here.
            </p>
            <div className="space-y-6">
              <div className="p-4 border border-gray-200 rounded-lg bg-white shadow-sm">
                <h3 className="text-lg font-medium text-gray-800">Profile</h3>
                <p className="text-gray-600 mt-1">Update your personal information.</p>
              </div>
              <div className="p-4 border border-gray-200 rounded-lg bg-white shadow-sm">
                <h3 className="text-lg font-medium text-gray-800">Billing</h3>
                <p className="text-gray-600 mt-1">Manage your subscription and payments.</p>
              </div>
              <div className="p-4 border border-gray-200 rounded-lg bg-white shadow-sm">
                <h3 className="text-lg font-medium text-gray-800">Team</h3>
                <p className="text-gray-600 mt-1">Add or remove team members.</p>
              </div>
              <div className="p-4 border border-gray-200 rounded-lg bg-white shadow-sm">
                <h3 className="text-lg font-medium text-gray-800">Notifications</h3>
                <p className="text-gray-600 mt-1">Customize how you're notified.</p>
              </div>
              <div className="p-4 border border-gray-200 rounded-lg bg-white shadow-sm">
                <h3 className="text-lg font-medium text-gray-800">Security</h3>
                <p className="text-gray-600 mt-1">Update your security settings.</p>
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
```

