### Sidebar.tsx
```tsx
import { useState } from 'react';

interface LinkItem {
  id: string;
  label: string;
  icon: JSX.Element;
}

export default function Sidebar({ activeLink, setActiveLink }: { activeLink: string; setActiveLink: (link: string) => void }) {
  const links: LinkItem[] = [
    {
      id: 'Profile',
      label: 'Profile',
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
        </svg>
      ),
    },
    {
      id: 'Billing',
      label: 'Billing',
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h10m-10-5h10m-10 5h10" />
        </svg>
      ),
    },
    {
      id: 'Team',
      label: 'Team',
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-8m0 8l-3-3m3 3l3-3" />
        </svg>
      ),
    },
    {
      id: 'Notifications',
      label: 'Notifications',
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-5 5v-5zM9 7H4l5-5v5z" />
        </svg>
      ),
    },
    {
      id: 'Security',
      label: 'Security',
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.952 11.952 0 0112 2.944a11.952 11.952 0 01-8.618 3.04A12 12 0 003 9c0 5.591 3.824 10.29 9 11.618 5.176-1.328 9-6.03 9-11.618 0-1.042-.133-2.052-.382-3.016z" />
        </svg>
      ),
    },
  ];

  return (
    <aside className="w-64 bg-white border-r border-gray-200 flex flex-col overflow-y-auto">
      <div className="p-4 border-b border-gray-100">
        <h2 className="text-lg font-semibold text-gray-800">Settings</h2>
      </div>
      <nav className="flex-1 p-4">
        {links.map((link) => (
          <button
            key={link.id}
            onClick={() => setActiveLink(link.id)}
            className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-left transition-colors duration-200 mb-1 ${
              activeLink === link.id
                ? 'bg-accent text-white'
                : 'text-gray-600 hover:bg-gray-100'
            }`}
          >
            {link.icon}
            <span className="font-medium">{link.label}</span>
          </button>
        ))}
      </nav>
      <footer className="p-4 border-t border-gray-100">
        <UserCard username="Alex" avatar="/default-avatar.png" />
      </footer>
    </aside>
  );
}
